_V59_CLASSES = ['BUILD_COOP', 'BUILD_PASTURE', 'CARE', 'COLLECT_FERTILIZER', 'DIG', 'DROP', 'EAST', 'FEED', 'FERTILIZE', 'HARVEST', 'NORTH', 'PASS', 'PICKUP|COW', 'PICKUP|FERTILIZER', 'PICKUP|GOOSE', 'PICKUP|WHEAT', 'PLACE|CARROT', 'PLACE|COW', 'PLACE|FERTILIZER', 'PLACE|GOOSE', 'PLACE|MELON', 'PLACE|MILK', 'PLACE|STRAWBERRY', 'PLACE|TOMATO', 'PLACE|WOOL', 'PLANT|CARROT', 'PLANT|MELON', 'PLANT|STRAWBERRY', 'PLANT|TOMATO', 'PLANT|WHEAT', 'SOUTH', 'WATER', 'WEST']
_V59_KEYS = ['actor', 'animal_here', 'carry', 'cash_bin', 'crop', 'fed_today', 'near_animal', 'near_crop', 'near_fertilizer', 'near_unfed', 'near_yield', 'shops', 'tile_kind', 'watered', 'x', 'y', 'yield_here']
_V59_RUNTIME = {}
def _v59_features(obs, seat, actor):
    farm=obs["farms"][seat]; coords=[farm.get("farmer",[0,0]),*farm.get("hands",[])]
    pos=coords[actor] if actor<len(coords) else [0,0]
    x,y=int(pos[0]),int(pos[1]); tiles=farm.get("tiles",[])
    tile=tiles[y][x] if y<len(tiles) and x<len(tiles[y]) and isinstance(tiles[y][x],dict) else {}
    inventories=obs.get("private",{}).get("inventories",[]); inv=inventories[actor] if actor<len(inventories) else {}
    targets={"yield":[],"crop":[],"animal":[],"unfed":[],"fertilizer":[]}
    for yy,row in enumerate(tiles):
        for xx,t in enumerate(row):
            if not isinstance(t,dict): continue
            if t.get("yield_units",0)>0: targets["yield"].append((xx,yy))
            if t.get("crop"): targets["crop"].append((xx,yy))
            if t.get("animal"): targets["animal"].append((xx,yy))
            if t.get("animal") and not t.get("fed_today"): targets["unfed"].append((xx,yy))
            if t.get("fertilizer_available"): targets["fertilizer"].append((xx,yy))
    f={"actor":actor,"x":x,"y":y,"tile_kind":tile.get("kind","EMPTY"),"crop":tile.get("crop","none"),
       "yield_here":int(tile.get("yield_units",0) or 0),"watered":int(bool(tile.get("watered"))),
       "animal_here":tile.get("animal","none"),"fed_today":int(bool(tile.get("fed_today"))),
       "carry":tuple(sorted((k,int(v)) for k,v in inv.items() if isinstance(v,(int,float)) and v)),
       "day":int(obs.get("day",0) or 0),"hour":int(obs.get("hour",0) or 0),
       "cash_bin":int(float(farm.get("money",0) or 0)//5000),
       "shops":len(obs.get("town",{}).get("unlocked_shops",[]))}
    for n,pts in targets.items(): f["near_"+n]=min((abs(x-a)+abs(y-b) for a,b in pts),default=99)
    return f
def _v59_predict(obs, seat, teacher_action):
    if not _V59_RUNTIME:
        import lightgbm as _v59_lgb, pandas as _v59_pd
        _V59_RUNTIME["model"]=_v59_lgb.Booster(model_str=_v59_gzip.decompress(_v59_b64.b85decode(_V59_MODEL_B85)).decode())
        _V59_RUNTIME["pd"]=_v59_pd
        _V59_RUNTIME["categories"]=_V59_RUNTIME["model"].pandas_categorical
    model=_V59_RUNTIME["model"]; pd=_V59_RUNTIME["pd"]; categories=_V59_RUNTIME["categories"]
    farm=obs["farms"][seat]; count=len(farm.get("hands",[])); feats=[_v59_features(obs,seat,i+1) for i in range(count)]
    if not feats: return []
    frame=pd.DataFrame([{k:str(f.get(k,"")) for k in _V59_KEYS} for f in feats])
    for i,k in enumerate(_V59_KEYS): frame[k]=pd.Categorical(frame[k],categories=categories[i])
    preds=model.predict(frame).argmax(axis=1)
    labels=[_V59_CLASSES[int(i)] for i in preds]
    templates={}
    for cmd in [teacher_action.get("farmer",["PASS"]),*teacher_action.get("hands",[])]:
        if isinstance(cmd,list): templates["|".join(map(str,cmd[:2]))]=cmd
    out=[]
    for i,lab in enumerate(labels):
        prior=teacher_action.get("hands",[])[i] if i<len(teacher_action.get("hands",[])) else ["PASS"]
        out.append(list(templates.get(lab,prior)))
    return out
_v59_teacher_agent=agent
def agent(obs,configuration=None):
    action=_v59_teacher_agent(obs,configuration)
    try:
        seat=int(obs.get("player",0)); action["hands"]=_v59_predict(obs,seat,action)
    except Exception:
        pass
    return action

def _kaggle_submission_entrypoint(obs,configuration=None): return agent(obs,configuration)
